# 1. 画布几何与配色（画布常量沿用 Pygame 版；配色见 _Palette）
# =============================================================================

TILE_SIZE = 64                  # 每格尺寸（像素）
TILE_GAP = 6                    # 格子间距
COLS = 6                        # 列数
ROWS = 8                        # 行数
MARGIN_X = 70                   # 左右边距
MARGIN_Y = 90                   # 上边距
BOTTOM = 70                     # 下边距
STEP = TILE_SIZE + TILE_GAP

# 扩展棋盘（外围一圈空边框，方便连线从外侧绕过）
EXT_ROWS = ROWS + 2
EXT_COLS = COLS + 2

BASE_W = MARGIN_X + COLS * STEP - TILE_GAP + MARGIN_X      # 500
BASE_H = MARGIN_Y + ROWS * STEP - TILE_GAP + BOTTOM        # 746

BOARD_W = COLS * STEP - TILE_GAP
BOARD_H = ROWS * STEP - TILE_GAP
BOARD_X = MARGIN_X - 8
BOARD_Y = MARGIN_Y - 8

EMPTY = -1                      # 棋盘空格标记
FPS = 60                        # 帧率
LINE_DURATION = 400             # 连线显示毫秒（消除动画）
BURST_DURATION = 360            # 消除光环毫秒
TOAST_DURATION = 1800           # 提示条毫秒


class _Palette:
    """配色：深色（原版的暗色霓虹风）与浅色两套，按**语义角色**取值。

    ⚠️ **为什么是"语义角色"而不是一堆色值常量**：原版把 17 个色值写成模块级 dict
    ``C``，另有 37 处内联 ``QColor(...)`` 字面量 —— 那些字面量绝大多数只是某基色的
    半透明变体（阴影、外发光、晕影）。与其为浅色再抄一遍这 54 个数，不如只定义
    **15 个角色**，其余交给 :meth:`edge` / :meth:`shadow` 之类的派生。

    ⚠️ **浅色不是把深色取反**：真正要逐个人工定夺的是**极性反转**那几处 ——
    深色下用白色半透明做提亮（``QColor(255,255,255,30)``），浅色下同样一句会
    **完全看不见**（白叠白），必须换成压暗的黑色叠层。凡「描边 / 分隔线 / 顶部反光 /
    内阴影」一律走 :meth:`edge`，不要直接写字面量。
    """

    #: 角色 -> (深色, 浅色)。两套的键必须完全一致。
    COLORS = {
        'bg0': ((38, 41, 58), (226, 232, 242)),
        'bg1': ((16, 17, 26), (247, 249, 253)),
        'panel': ((35, 38, 50), (250, 251, 254)),
        'panel_lo': ((24, 26, 36), (233, 237, 246)),
        'slot': ((25, 28, 36), (228, 232, 242)),
        'tile_bg': ((42, 46, 62), (255, 255, 255)),
        'tile_lo': ((20, 22, 32), (238, 241, 248)),
        'sel': ((255, 215, 0), (214, 158, 0)),
        'line': ((0, 255, 200), (0, 160, 132)),
        'hint': ((255, 214, 64), (198, 148, 0)),
        'txt': ((200, 200, 210), (32, 36, 48)),
        'txt_dim': ((140, 140, 155), (92, 100, 118)),
        'gold': ((255, 215, 0), (198, 148, 0)),
        'neon2': ((86, 232, 255), (0, 140, 178)),
        'neon': ((255, 72, 162), (196, 32, 112)),
    }

    #: 当前主题是否为深色（由 :meth:`use_dark` 维护）。
    dark = True

    @classmethod
    def use_dark(cls, dark: bool) -> None:
        """切换当前主题（深色 / 浅色）。"""
        cls.dark = bool(dark)

    @classmethod
    def c(cls, role: str, alpha: int = 255) -> QColor:
        """取一个角色对应的颜色；``alpha`` 给 0~255（默认不透明）。"""
        r, g, b = cls.COLORS[role][0 if cls.dark else 1]
        return QColor(r, g, b, alpha)

    @classmethod
    def edge(cls, alpha: int = 22) -> QColor:
        """半透明的「提亮/压暗」叠层 —— 深色主题下是白，浅色主题下是黑。

        ⚠️ 这是两套主题**唯一靠极性反转**的地方：深色下 ``QColor(255,255,255,22)``
        是一条淡淡的高光分隔线，浅色下同样一句会**完全看不见**（白叠白），
        必须换成黑色叠层。
        """
        return QColor(255, 255, 255, alpha) if cls.dark else QColor(0, 0, 0, alpha)

    @classmethod
    def shadow(cls, alpha: int = 90) -> QColor:
        """投影：两套主题都是黑，但浅色下要更淡（否则在白底上糊成一块）。"""
        return QColor(0, 0, 0, alpha if cls.dark else max(18, int(alpha * 0.28)))


def COL(role: str, alpha: int = 255) -> QColor:
    """取语义色（模块内的短名，等价于 :meth:`_Palette.c`）。

    ⚠️ 它是**函数**不是常量 —— 每次调用都按**当时**的主题取值，所以切换主题后
    同一行代码自然就画出新配色，不需要重建任何东西。
    """
    return _Palette.c(role, alpha)


def EDGE(alpha: int = 22) -> QColor:
    """取极性化的提亮/压暗叠层（等价于 :meth:`_Palette.edge`）。"""
    return _Palette.edge(alpha)


def SHADOW(alpha: int = 90) -> QColor:
    """取投影色（等价于 :meth:`_Palette.shadow`）。"""
    return _Palette.shadow(alpha)


FONT_FAMILY = "Microsoft YaHei"


# =============================================================================
# 2. 坐标换算（与 Pygame 版逐字一致）
# =============================================================================

def grid_to_pixel(r: int, c: int) -> tuple[float, float]:
    """棋盘格中心 → 画布像素坐标（含外围空边框的格子，可能落在棋盘之外）"""
    x = MARGIN_X + (c - 1) * STEP + TILE_SIZE // 2
    y = MARGIN_Y + (r - 1) * STEP + TILE_SIZE // 2
    return float(x), float(y)


def grid_to_point(r: int, c: int) -> QPointF:
    x, y = grid_to_pixel(r, c)
    return QPointF(x, y)


def cell_rect(r: int, c: int) -> QRectF:
    x, y = grid_to_pixel(r, c)
    return QRectF(x - TILE_SIZE / 2, y - TILE_SIZE / 2, TILE_SIZE, TILE_SIZE)


# =============================================================================
# 3. 棋盘模型与寻路（算法与 Pygame 版一致）
# =============================================================================

Board = list  # Board = list[list[int]]，EXT_ROWS × EXT_COLS，EMPTY 表示空格


def make_grid() -> Board:
    return [[EMPTY for _ in range(EXT_COLS)] for _ in range(EXT_ROWS)]


def is_line_clear(g: Board, r1: int, c1: int, r2: int, c2: int) -> bool:
    """同一直线上的两个格子之间是否全是空格（不含两端）"""
    if r1 == r2:                 # 水平
        step = 1 if c2 > c1 else -1
        for c in range(c1 + step, c2, step):
            if g[r1][c] != EMPTY:
                return False
        return True
    elif c1 == c2:               # 垂直
        step = 1 if r2 > r1 else -1
        for r in range(r1 + step, r2, step):
            if g[r][c1] != EMPTY:
                return False
        return True
    return False                 # 不在同一直线


def find_path(g: Board, r1: int, c1: int, r2: int, c2: int) -> list[tuple[int, int]] | None:
    """寻找连接路径（≤2 折），返回路径点列表或 None"""
    if (r1, c1) == (r2, c2):
        return None
    if g[r1][c1] != g[r2][c2] or g[r1][c1] == EMPTY:
        return None

    # ── 0 折：同一直线直接可达 ──
    if (r1 == r2 or c1 == c2) and is_line_clear(g, r1, c1, r2, c2):
        return [(r1, c1), (r2, c2)]

    # ── 1 折：L 形 ──
    if g[r1][c2] == EMPTY and is_line_clear(g, r1, c1, r1, c2) and is_line_clear(g, r1, c2, r2, c2):
        return [(r1, c1), (r1, c2), (r2, c2)]
    if g[r2][c1] == EMPTY and is_line_clear(g, r1, c1, r2, c1) and is_line_clear(g, r2, c1, r2, c2):
        return [(r1, c1), (r2, c1), (r2, c2)]

    # ── 2 折：扫描行 ──
    for r in range(EXT_ROWS):
        if r == r1 or r == r2:
            continue
        if g[r][c1] == EMPTY and g[r][c2] == EMPTY:
            if (is_line_clear(g, r1, c1, r, c1) and
                is_line_clear(g, r, c1, r, c2) and
                is_line_clear(g, r, c2, r2, c2)):
                return [(r1, c1), (r, c1), (r, c2), (r2, c2)]

    # ── 2 折：扫描列 ──
    for c in range(EXT_COLS):
        if c == c1 or c == c2:
            continue
        if g[r1][c] == EMPTY and g[r2][c] == EMPTY:
            if (is_line_clear(g, r1, c1, r1, c) and
                is_line_clear(g, r1, c, r2, c) and
                is_line_clear(g, r2, c, r2, c2)):
                return [(r1, c1), (r1, c), (r2, c), (r2, c2)]

    return None


def live_cells(g: Board) -> list[tuple[int, int]]:
    return [(r, c) for r in range(1, ROWS + 1) for c in range(1, COLS + 1)
            if g[r][c] != EMPTY]


def has_valid_moves(g: Board) -> bool:
    """检查是否存在可消除的对"""
    cells = live_cells(g)
    for i in range(len(cells)):
        for j in range(i + 1, len(cells)):
            if find_path(g, cells[i][0], cells[i][1], cells[j][0], cells[j][1]):
                return True
    return False


def find_hint(g: Board) -> tuple[tuple[int, int], tuple[int, int]] | None:
    """找一对可连的头像，返回 ((r1,c1),(r2,c2)) 或 None"""
    cells = live_cells(g)
    for i in range(len(cells)):
        for j in range(i + 1, len(cells)):
            if find_path(g, cells[i][0], cells[i][1], cells[j][0], cells[j][1]):
                return cells[i], cells[j]
    return None


def build_grid(n_types: int) -> Board:
    """随机生成棋盘：每种头像至少 1 对，剩余对数轮流分配（保证每种都是偶数个）"""
    g = make_grid()
    if n_types <= 0:
        return g

    total = COLS * ROWS
    num_pairs = total // 2

    pairs_per = [1] * min(n_types, num_pairs)
    for i in range(num_pairs - len(pairs_per)):
        pairs_per[i % len(pairs_per)] += 1

    tile_indices = []
    for i, p in enumerate(pairs_per):
        tile_indices.extend([i] * (p * 2))
    random.shuffle(tile_indices)

    idx = 0
    for r in range(1, ROWS + 1):
        for c in range(1, COLS + 1):
            g[r][c] = tile_indices[idx]
            idx += 1
    return g


def shuffle_grid(g: Board) -> None:
    """重排剩余棋子（空格不动）"""
    remaining = [g[r][c] for r, c in live_cells(g)]
    random.shuffle(remaining)
    idx = 0
    for r, c in live_cells(g):
        g[r][c] = remaining[idx]
        idx += 1


# =============================================================================
# 4. 头像加载
# =============================================================================

IMG_EXTS = {".png", ".jpg", ".jpeg", ".bmp", ".gif", ".webp"}



def load_avatars(size: int = 0) -> list[tuple[str, QPixmap]]:
    """把内联的 base64 头像解成 QPixmap（居中裁方；默认**保持原生分辨率**）。

    原版是从 ``avatars/`` 文件夹读盘并缩到 ``TILE_SIZE``；这里改成读
    :data:`AVATARS_B64`，同时**不再预缩到格子尺寸**。

    ⚠️ **为什么默认不缩**：``TILE_SIZE`` 是**逻辑**像素，而高 DPI 屏幕上
    一个格子要画 ``devicePixelRatio`` 倍的**物理**像素（2x 屏就是 128）。
    若这里先缩到 64，画的时候再放大回去 —— 白丢一半精度，还多一次缩放。
    内联数据本来就是 200，直接原样用，让 ``QPainter.drawPixmap(rect, pm, src)``
    在绘制时按实际大小缩放（它本来就支持，且有 SmoothPixmapTransform）。

    Args:
        size: 目标边长。**默认 0 = 保持原生分辨率**（当前内联数据是 200）；
            给正数则强制缩到该边长（自测 / 特殊场合用）。

    Returns:
        list[tuple[str, QPixmap]]: ``(名字, 头像)`` 列表；没有 Qt 时返回空列表。

    ⚠️ **解码失败的那张跳过、不抛异常**：一张坏图不该让整个彩蛋打不开。
    """
    if not HAVE_QT:
        return []

    out: list[tuple[str, QPixmap]] = []
    for idx, b64 in enumerate(AVATARS_B64):
        try:
            raw = base64.b64decode(b64)
            pm = QPixmap()
            if not pm.loadFromData(raw, 'JPG'):
                print(f'跳过无法解码的头像 #{idx}')
                continue
            side = min(pm.width(), pm.height())
            if pm.width() != pm.height():
                pm = pm.copy((pm.width() - side) // 2,
                             (pm.height() - side) // 2, side, side)
            if size > 0 and pm.width() != size:
                pm = pm.scaled(size, size,
                               Qt.AspectRatioMode.IgnoreAspectRatio,
                               Qt.TransformationMode.SmoothTransformation)
            out.append((f'avatar_{idx:02d}', pm))
        except Exception as err:        # pragma: no cover - 坏数据兜底
            print(f'跳过无法解码的头像 #{idx}: {err}')
    return out



# =============================================================================
# 5. 游戏窗口
# =============================================================================


class LinkGame(QWidget):
    """连连看主窗口：所有内容都是 paintEvent 自绘，按 BASE_W×BASE_H 等比缩放适配窗口。"""

    def __init__(self) -> None:
        super().__init__()
        self.setWindowTitle("连连看")
        self.setMinimumSize(int(BASE_W * 0.72), int(BASE_H * 0.72))
        self.resize(BASE_W, BASE_H)
        self.setMouseTracking(True)

        # ── 资源与棋盘 ──
        self.avatars: list[tuple[str, QPixmap]] = load_avatars()
        self.g: Board = make_grid()
        self.selected: tuple[int, int] | None = None
        self.hint_pair: tuple[tuple[int, int], tuple[int, int]] | None = None
        self.conn_path: list[tuple[int, int]] = []
        self.conn_start = 0                     # 连线开始时刻（毫秒）
        self.pairs_left = 0
        self.moves = 0
        self.hover: tuple[int, int] | None = None
        self.bursts: list[tuple[float, float, int]] = []   # (x, y, 开始时刻)
        self.toast: tuple[str, int] | None = None
        self.won = False
        self.start_ms = None                    # 第一次点击作为计时起点

        # ── 时钟：QElapsedTimer 只作时间戳，QTimer 负责帧 ──
        self.clock = QElapsedTimer()
        self.clock.start()
        self.frame_count = 0
        self.timer = QTimer(self)
        self.timer.setInterval(int(1000 / FPS))
        self.timer.timeout.connect(self._frame)

        self.new_game()
        if self.avatars:
            self.timer.start()
        else:
            self.toast = ("avatars/ 里没有可用图片", self.now())

    # ------------------------------------------------------------ 时间
    def now(self) -> int:
        return int(self.clock.elapsed())

    def elapsed_s(self) -> int:
        if self.start_ms is None:
            return 0
        return (self.now() - self.start_ms) // 1000

    def _frame(self) -> None:
        self.frame_count += 1
        t = self.now()
        if self.conn_path and t - self.conn_start >= LINE_DURATION:
            self.resolve_connection()
        self.bursts = [b for b in self.bursts if t - b[2] < BURST_DURATION]
        if self.toast and t - self.toast[1] > TOAST_DURATION:
            self.toast = None
        self.update()

    # ------------------------------------------------------------ 局面
    def new_game(self) -> None:
        if not self.avatars:
            return
        self.g = build_grid(len(self.avatars))
        self.selected = None
        self.hint_pair = None
        self.conn_path = []
        self.bursts = []
        self.moves = 0
        self.won = False
        self.pairs_left = COLS * ROWS // 2
        self.start_ms = None
        self.auto_shuffle_if_needed()

    def auto_shuffle_if_needed(self) -> None:
        """无可用配对时自动重排，最多 10 次；仍无解则重开棋盘"""
        for _ in range(10):
            if has_valid_moves(self.g):
                return
            shuffle_grid(self.g)
        self.new_game()

    def remove_pair(self) -> None:
        """消除连接的一对"""
        (r1, c1), (r2, c2) = self.conn_path[0], self.conn_path[-1]
        for r, c in ((r1, c1), (r2, c2)):
            x, y = grid_to_pixel(r, c)
            self.bursts.append((x, y, self.now()))
            self.g[r][c] = EMPTY
        self.pairs_left = max(0, self.pairs_left - 1)
        self.moves += 1

    def resolve_connection(self) -> None:
        """连线动画结束 → 消除，并在需要时自动重排"""
        self.remove_pair()
        self.conn_path = []
        self.hint_pair = None
        if self.pairs_left > 0:
            self.auto_shuffle_if_needed()
        else:
            self.won = True

    # ------------------------------------------------------------ 交互
    def click_cell(self, pos: QPointF) -> tuple[int, int] | None:
        """画布坐标 → 棋盘格；点空格或棋盘外返回 None（比 Pygame 版宽容半格）"""
        px, py = pos.x(), pos.y()
        c = int((px - MARGIN_X) // STEP) + 1
        r = int((py - MARGIN_Y) // STEP) + 1
        if not (1 <= r <= ROWS and 1 <= c <= COLS):
            return None
        if self.g[r][c] == EMPTY:
            return None
        # 落在格子中心的 0.5 格外仍算命中，避免手指/鼠标略偏就点不中
        x, y = grid_to_pixel(r, c)
        tol = TILE_SIZE / 2 + TILE_GAP / 2
        if abs(px - x) > tol or abs(py - y) > tol:
            return None
        return r, c

    def handle_click(self, pos: QPointF) -> None:
        if self.conn_path or self.won:      # 动画播放中 / 已通关，忽略点击
            return
        self.hint_pair = None               # 点了就清除提示
        cell = self.click_cell(pos)
        if cell is None:
            return
        if self.start_ms is None:
            self.start_ms = self.now()

        if self.selected is None:
            self.selected = cell
        elif self.selected == cell:
            self.selected = None            # 取消选中
        elif self.g[self.selected[0]][self.selected[1]] == self.g[cell[0]][cell[1]]:
            # 同种头像 → 尝试寻路
            path = find_path(self.g, self.selected[0], self.selected[1], cell[0], cell[1])
            if path:
                self.conn_path = list(path)
                self.conn_start = self.now()
                self.selected = None
            else:
                self.selected = cell        # 连不上，切换选中
        else:
            self.selected = cell            # 不同头像，切换选中

    def show_hint(self) -> None:
        if self.conn_path or self.won:
            return
        pair = find_hint(self.g)
        self.hint_pair = pair
        if pair:
            print(f"提示: {pair[0]} <-> {pair[1]}")
        else:
            print("提示: 没有可连接的对了，按空格洗牌")
            self.toast = ("没有可连的对子了，按空格洗牌", self.now())

    def do_shuffle(self, manual: bool = False) -> None:
        if self.conn_path or self.won or not self.avatars:
            return
        shuffle_grid(self.g)
        self.auto_shuffle_if_needed()
        self.selected = None
        self.hint_pair = None
        if manual:
            self.toast = ("已重排剩余棋子", self.now())

    # =====================================================================
    # 渲染
    # =====================================================================

    def canvas_transform(self) -> tuple[float, float, float]:
        """返回 (缩放, 横向信箱边, 纵向信箱边)；paintEvent 与鼠标换算共用一份来源"""
        w, h = self.width(), self.height()
        s = min(w / BASE_W, h / BASE_H)
        return s, (w - BASE_W * s) / 2.0, (h - BASE_H * s) / 2.0

    def paintEvent(self, ev) -> None:  # noqa: N802
        w, h = self.width(), self.height()
        pr = QPainter(self)
        pr.setRenderHint(QPainter.RenderHint.Antialiasing, True)
        pr.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform, True)
        pr.setRenderHint(QPainter.RenderHint.TextAntialiasing, True)

        # 窗口底色（信箱边也好看）
        bg = QRadialGradient(QPointF(w / 2.0, h * 0.34), max(w, h) * 0.78)
        bg.setColorAt(0.0, COL('bg0'))
        bg.setColorAt(1.0, COL('bg1'))
        pr.fillRect(self.rect(), QBrush(bg))

        # 对齐到设备像素，避免等比缩放后文字/描边发虚
        s, ox, oy = self.canvas_transform()
        dpr = self.devicePixelRatioF()
        pr.translate(round(ox * dpr) / dpr, round(oy * dpr) / dpr)
        pr.scale(s, s)

        t = self.now()
        self._draw_panel(pr)
        self._draw_tiles(pr, t)
        self._draw_hint(pr, t)
        self._draw_selection(pr, t)
        self._draw_bursts(pr, t)
        self._draw_connection(pr)
        # HUD 最后画：连线允许走棋盘外圈（第 0 行 / 第 9 行），会横穿标题栏那一条，
        # 所以标题必须压在连线之上，否则文字被一条青线划开。
        self._draw_header(pr)
        self._draw_footer(pr, t)
        if self.won:
            self._draw_win(pr, t)
        pr.end()

    # ---------------------------------------------------------------- 棋盘
    def _draw_panel(self, pr: QPainter) -> None:
        panel = QRectF(BOARD_X, BOARD_Y, BOARD_W + 16, BOARD_H + 16)
        # 外阴影 + 凹槽边
        pr.setPen(Qt.PenStyle.NoPen)
        pr.setBrush(SHADOW(90))
        pr.drawRoundedRect(panel.adjusted(-6, 2, 6, 10), 16, 16)

        g = QLinearGradient(panel.topLeft(), panel.bottomLeft())
        g.setColorAt(0.0, COL('panel'))
        g.setColorAt(1.0, COL('panel_lo'))
        pr.setBrush(QBrush(g))
        pr.setPen(QPen(EDGE(170), 1.4))
        pr.drawRoundedRect(panel, 12, 12)

        # 空格凹槽（棋盘底纹）
        pr.setPen(Qt.PenStyle.NoPen)
        for r in range(1, ROWS + 1):
            for c in range(1, COLS + 1):
                pr.setBrush(COL('slot'))
                pr.drawRoundedRect(cell_rect(r, c), 7, 7)

    def _draw_tiles(self, pr: QPainter, t: int) -> None:
        hover_ok = self.hover if (not self.conn_path and not self.won) else None
        for r in range(1, ROWS + 1):
            for c in range(1, COLS + 1):
                idx = self.g[r][c]
                if idx == EMPTY:
                    continue
                rect = cell_rect(r, c)
                self._draw_tile(pr, rect, idx, self.selected == (r, c), hover_ok == (r, c))

    def _draw_tile(self, pr: QPainter, rect: QRectF, idx: int, selected: bool,
                   hovered: bool) -> None:
        pm = self.avatars[idx][1]
        # 投影
        pr.setPen(Qt.PenStyle.NoPen)
        pr.setBrush(SHADOW(110))
        pr.drawRoundedRect(rect.adjusted(0, 2, 0, 4), 9, 9)

        # 底（透明 PNG 也不会露出面板底色）
        g = QLinearGradient(rect.topLeft(), rect.bottomRight())
        g.setColorAt(0.0, COL('tile_bg'))
        g.setColorAt(1.0, COL('tile_lo'))
        pr.setBrush(QBrush(g))
        pr.drawRoundedRect(rect, 9, 9)

        # 头像
        path = QPainterPath()
        path.addRoundedRect(rect, 9, 9)
        pr.save()
        pr.setClipPath(path)
        pr.drawPixmap(rect, pm, QRectF(pm.rect()))
        pr.restore()

        # 描边
        pr.setBrush(Qt.BrushStyle.NoBrush)
        pr.setPen(QPen(EDGE(30), 1.2))
        pr.drawRoundedRect(rect.adjusted(0.6, 0.6, -0.6, -0.6), 8.6, 8.6)

        if hovered and not selected:
            pr.setPen(QPen(EDGE(90), 2.0))
            pr.drawRoundedRect(rect.adjusted(1.2, 1.2, -1.2, -1.2), 8, 8)

    def _draw_selection(self, pr: QPainter, t: int) -> None:
        if self.selected is None:
            return
        rect = cell_rect(*self.selected)
        k = 0.5 + 0.5 * math.sin(t * 0.008)
        pr.setBrush(Qt.BrushStyle.NoBrush)
        pr.setPen(QPen(COL('sel', int(120 + 100 * k)), 7.0))
        pr.drawRoundedRect(rect.adjusted(-2.5, -2.5, 2.5, 2.5), 11, 11)
        pr.setPen(QPen(COL('sel'), 3.0))
        pr.drawRoundedRect(rect.adjusted(-2.5, -2.5, 2.5, 2.5), 11, 11)

    # ---------------------------------------------------------------- 提示
    def _draw_hint(self, pr: QPainter, t: int) -> None:
        if not self.hint_pair:
            return
        k = 0.5 + 0.5 * math.sin(t * 0.006)          # 0..1 脉冲
        col = QColor(int(220 + 35 * k), int(200 + 55 * k), int(100 * k))
        for r, c in self.hint_pair:
            rect = cell_rect(r, c)
            # 外光晕：径向渐变光圈（Pygame 版是三层半透明方框，这里换成真正的光晕）
            glow = QRadialGradient(rect.center(), TILE_SIZE * 1.05)
            glow.setColorAt(0.45, QColor(col.red(), col.green(), col.blue(), int(40 + 60 * k)))
            glow.setColorAt(1.0, QColor(col.red(), col.green(), col.blue(), 0))
            pr.setPen(Qt.PenStyle.NoPen)
            pr.setBrush(QBrush(glow))
            pr.drawEllipse(rect.center(), TILE_SIZE * 1.05, TILE_SIZE * 1.05)
            # 粗边框
            pr.setBrush(Qt.BrushStyle.NoBrush)
            pr.setPen(QPen(col, 6.0))
            pr.drawRoundedRect(rect.adjusted(-2, -2, 2, 2), 11, 11)

    def _draw_connection(self, pr: QPainter) -> None:
        if len(self.conn_path) < 2:
            return
        pts = [grid_to_point(r, c) for r, c in self.conn_path]
        path = QPainterPath(pts[0])
        for p in pts[1:]:
            path.lineTo(p)
        pr.setBrush(Qt.BrushStyle.NoBrush)
        # 外发光 + 实线
        pr.setPen(QPen(COL('line', 70), 13.0, Qt.PenStyle.SolidLine,
                       Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin))
        pr.drawPath(path)
        pr.setPen(QPen(COL('line'), 5.0, Qt.PenStyle.SolidLine,
                       Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin))
        pr.drawPath(path)
        pr.setPen(QPen(EDGE(200), 1.6))
        pr.drawPath(path)
        # 端点
        pr.setPen(QPen(EDGE(200), 2.0))
        pr.setBrush(COL('line'))
        for p in pts:
            pr.drawEllipse(p, 7.0, 7.0)

    def _draw_bursts(self, pr: QPainter, t: int) -> None:
        for x, y, t0 in self.bursts:
            k = min(1.0, (t - t0) / BURST_DURATION)
            pr.setBrush(Qt.BrushStyle.NoBrush)
            for scale, width in ((1.0, 3.0), (1.6, 1.6)):
                r = (TILE_SIZE / 2 + 6) * scale * (0.55 + 0.75 * k)
                pr.setPen(QPen(COL('line', int(190 * (1 - k))), width))
                pr.drawEllipse(QPointF(x, y), r, r)

    # ---------------------------------------------------------------- HUD
    def _draw_header(self, pr: QPainter) -> None:
        # 顶部压一层不透明晕影：连线可以走棋盘外圈（第 0 行就是标题栏那一条），
        # 让它从标题背后穿过，而不是把文字划断。
        scrim = QLinearGradient(QPointF(0, 0), QPointF(0, BOARD_Y - 2))
        scrim.setColorAt(0.0, COL('bg1', 252))
        scrim.setColorAt(0.85, COL('bg1', 250))
        scrim.setColorAt(1.0, COL('bg1', 0))
        pr.setPen(Qt.PenStyle.NoPen)
        pr.setBrush(QBrush(scrim))
        pr.drawRect(QRectF(0, 0, BASE_W, BOARD_Y - 2))

        # 标题（外发光）
        f = QFont(FONT_FAMILY, 20)
        f.setWeight(QFont.Weight.Black)
        f.setLetterSpacing(QFont.SpacingType.AbsoluteSpacing, 6)
        pr.setFont(f)
        pr.setPen(COL('neon2', 45))
        pr.drawText(QPointF(MARGIN_X + 1.5, 45.5), "连 连 看")
        pr.setPen(COL('txt'))
        pr.drawText(QPointF(MARGIN_X, 44), "连 连 看")

        # 副标题：排在标题下方，只占左侧（右侧留给状态数字，不会撞车）
        f2 = QFont(FONT_FAMILY, 10)
        pr.setFont(f2)
        pr.setPen(COL('txt_dim'))
        pr.drawText(QPointF(MARGIN_X + 2, 68), f"{len(self.avatars)} 种头像  ·  两折之内可连")

        # 右侧：剩余对数 · 用时
        f3 = QFont(FONT_FAMILY, 14)
        f3.setWeight(QFont.Weight.DemiBold)
        pr.setFont(f3)
        fm = QFontMetrics(f3)
        pairs = str(self.pairs_left)
        tm = self._time_text()
        w_all = fm.horizontalAdvance("剩余  对  ·  用时 ") + fm.horizontalAdvance(pairs) \
            + fm.horizontalAdvance(tm)
        x = BASE_W - MARGIN_X - w_all
        pr.setPen(COL('txt_dim'))
        pr.drawText(QPointF(x, 46), "剩余 ")
        x += fm.horizontalAdvance("剩余 ")
        pr.setPen(COL('gold'))
        pr.drawText(QPointF(x, 46), pairs)
        x += fm.horizontalAdvance(pairs)
        pr.setPen(COL('txt_dim'))
        pr.drawText(QPointF(x, 46), " 对  ·  用时 ")
        x += fm.horizontalAdvance(" 对  ·  用时 ")
        pr.setPen(COL('neon2'))
        pr.drawText(QPointF(x, 46), tm)

        # 分隔线
        pr.setPen(QPen(EDGE(90), 1.0))
        pr.drawLine(QPointF(MARGIN_X - 8, BOARD_Y - 12), QPointF(BASE_W - MARGIN_X + 8, BOARD_Y - 12))

    def _time_text(self) -> str:
        s = self.elapsed_s()
        return f"{s // 60:02d}:{s % 60:02d}"

    def _draw_footer(self, pr: QPainter, t: int) -> None:
        # 同样的不透明晕影：连线走到棋盘下沿时不会压到操作提示
        scrim = QLinearGradient(QPointF(0, BASE_H), QPointF(0, BOARD_Y + BOARD_H + 16))
        scrim.setColorAt(0.0, COL('bg1', 246))
        scrim.setColorAt(0.8, COL('bg1', 240))
        scrim.setColorAt(1.0, COL('bg1', 0))
        pr.setPen(Qt.PenStyle.NoPen)
        pr.setBrush(QBrush(scrim))
        pr.drawRect(QRectF(0, BOARD_Y + BOARD_H + 16, BASE_W, BASE_H - BOARD_Y - BOARD_H - 16))

        # 分两行，避免一行放不下右半边（中文一多就溢出窗口）
        f = QFont(FONT_FAMILY, 10)
        pr.setFont(f)
        pr.setPen(COL('txt_dim'))
        left = "左键消除  ·  右键/F1 提示"
        right = "空格洗牌  ·  R 重开  ·  Esc 退出"
        fm = QFontMetrics(f)
        pr.drawText(QPointF(MARGIN_X - 8, BASE_H - 14), left)
        pr.drawText(QPointF(BASE_W - MARGIN_X + 8 - fm.horizontalAdvance(right), BASE_H - 14), right)

        if self.toast:
            text, t0 = self.toast
            k = 1.0 - min(1.0, max(0.0, (t - t0 - (TOAST_DURATION - 600)) / 600.0))
            f2 = QFont(FONT_FAMILY, 11)
            f2.setWeight(QFont.Weight.DemiBold)
            pr.setFont(f2)
            pr.setPen(COL('hint', int(235 * k)))
            fm2 = QFontMetrics(f2)
            pr.drawText(QPointF((BASE_W - fm2.horizontalAdvance(text)) / 2.0,
                                BASE_H - 32), text)

    def _draw_win(self, pr: QPainter, t: int) -> None:
        pr.fillRect(QRectF(0, 0, BASE_W, BASE_H), SHADOW(170))
        card = QRectF(48, BASE_H / 2 - 108, BASE_W - 96, 216)
        pr.setPen(Qt.PenStyle.NoPen)
        pr.setBrush(SHADOW(130))
        pr.drawRoundedRect(card.adjusted(0, 6, 0, 12), 22, 22)

        g = QLinearGradient(card.topLeft(), card.bottomLeft())
        g.setColorAt(0.0, COL('panel'))
        g.setColorAt(1.0, COL('panel_lo'))
        pr.setBrush(QBrush(g))
        pr.setPen(QPen(COL('hint', 150), 2.0))
        pr.drawRoundedRect(card, 22, 22)

        # 标题（带轻微呼吸）
        k = 0.5 + 0.5 * math.sin(t * 0.005)
        f = QFont(FONT_FAMILY, 30)
        f.setWeight(QFont.Weight.Black)
        f.setLetterSpacing(QFont.SpacingType.AbsoluteSpacing, 3)
        pr.setFont(f)
        title = "恭 喜 通 关 !"
        fm = QFontMetrics(f)
        tx = (BASE_W - fm.horizontalAdvance(title)) / 2.0
        pr.setPen(COL('gold', int(80 + 60 * k)))
        pr.drawText(QPointF(tx + 2, card.top() + 68), title)
        pr.setPen(COL('gold'))
        pr.drawText(QPointF(tx, card.top() + 66), title)

        f2 = QFont(FONT_FAMILY, 14)
        pr.setFont(f2)
        pr.setPen(COL('txt'))
        pr.drawText(QRectF(card.left(), card.top() + 92, card.width(), 24),
                    Qt.AlignmentFlag.AlignCenter,
                    f"用时 {self._time_text()}   ·   {self.moves} 轮消除   ·   {COLS * ROWS // 2} 对全部清空")

        f3 = QFont(FONT_FAMILY, 12)
        pr.setFont(f3)
        pr.setPen(COL('txt_dim'))
        pr.drawText(QRectF(card.left(), card.bottom() - 40, card.width(), 22),
                    Qt.AlignmentFlag.AlignCenter, "按 R 重新开始")

    # =====================================================================
    # 输入
    # =====================================================================

    def to_canvas(self, x: float, y: float) -> QPointF:
        """控件像素坐标 → 画布逻辑坐标（与 paintEvent 的变换互逆）"""
        s, ox, oy = self.canvas_transform()
        return QPointF((x - ox) / s, (y - oy) / s)

    def mousePressEvent(self, ev) -> None:  # noqa: N802
        if ev.button() == Qt.MouseButton.LeftButton:
            self.handle_click(self.to_canvas(ev.position().x(), ev.position().y()))
        elif ev.button() == Qt.MouseButton.RightButton:
            self.show_hint()
        self.update()

    def mouseMoveEvent(self, ev) -> None:  # noqa: N802
        cell = self.click_cell(self.to_canvas(ev.position().x(), ev.position().y()))
        if cell != self.hover:
            self.hover = cell
            self.setCursor(Qt.CursorShape.PointingHandCursor if cell
                           else Qt.CursorShape.ArrowCursor)
            self.update()

    def leaveEvent(self, ev) -> None:  # noqa: N802
        if self.hover is not None:
            self.hover = None
            self.unsetCursor()
            self.update()

    def keyPressEvent(self, ev) -> None:  # noqa: N802
        k = ev.key()
        if k == Qt.Key.Key_Escape:
            self.close()
        elif k == Qt.Key.Key_Space:
            self.do_shuffle(manual=True)
        elif k == Qt.Key.Key_R:
            self.new_game()
            self.toast = ("新的一局，加油！", self.now())
        elif k in (Qt.Key.Key_F1, Qt.Key.Key_H):
            self.show_hint()
        else:
            super().keyPressEvent(ev)
        self.update()


# =============================================================================
# 7. 标签页适配（zmlx 专有，原版没有这一节）
# =============================================================================

class LianliankanView(LinkGame):
    """连连看控件（给 zmlx 用的那个）。

    ``LinkGame`` 是原版游戏控件，规则一行未改；本子类只补**标签页生命周期**：
    切走时停表、切回来续表、关标签页时收尾，以及跟随界面换肤。

    ⚠️ **为什么必须停表**：原版是独立窗口，开着一局就一直是 60 FPS 重绘；
    放进标签页后它可能被切到后台、甚至从未被打开（``gui_restore`` 恢复的标签）。
    不停表就是让一个没人在看的游戏白烧 CPU。

    ⚠️ **为什么必须重置时钟基准**：``_frame`` 只做 ``update()``，本身不依赖
    时间差；但 ``conn_start`` / ``bursts`` / ``toast`` 都拿 ``now()`` 做绝对时间戳，
    停表几分钟后切回来，那些"已过多久"的判断会一次性全部成立（连线和光环
    瞬间消失）。所以续表前不做任何补偿 —— 停表期间本来就没有动画在跑，
    时间戳继续走是**正确**的（动画在停表那一刻就已经冻结在画面上）。
    """

    def __init__(self, parent=None):
        super().__init__()
        if parent is not None:
            self.setParent(parent)
        #: 宿主注入的"关掉本标签页"回调（``TabWidget.close_tab``）。
        self.close_callback = None
        #: 是否正在被关闭（``cleanup_before_tab_close`` 置位）。
        #: ⚠️ 用它把"关标签"与"切标签"两种 ``hideEvent`` 区分开。
        self._closing = False
        #: 是否已连上 ``QApplication.paletteChanged``。
        self._palette_hooked = False
        # 开局就把当前主题对齐一次（控件可能在深色界面里被创建）
        self._apply_theme()
        # ⚠️ **主题信号在这里就接上**，不等 ``_bind_close_callback``：
        #    那个只在 ``show_lianliankan()`` 里调（那时控件已进 TabWidget）。
        #    但 ``test_1()``（独立窗口自测）永远走不到那里 —— 那样独立窗口下
        #    换主题就不跟着变，是不该有的差异。
        self._connect_palette_signal()

    # ------------------------------------------------------------ 主题
    def _apply_theme(self) -> None:
        """按宿主当前的调色板亮暗，设置 ``_Palette`` 的模式。"""
        try:
            dark = self._host_is_dark()
            _Palette.use_dark(dark)
        except Exception:
            pass

    @staticmethod
    def _host_is_dark() -> bool:
        """宿主当前是不是深色主题。

        判据用 ``QPalette.Window`` 的亮度 —— 这是唯一不依赖具体样式表、
        且在 PyQt5 / PyQt6 上都稳定的办法（``Qt.GlobalColor`` 的语义色
        在自定义 QSS 下不可靠）。亮度 < 128 视为深色。
        """
        app = QApplication.instance()
        if app is None:
            return True                     # 没有 app（自测）时沿用原版深色
        col = app.palette().color(QtGui.QPalette.ColorRole.Window)
        return col.lightness() < 128

    def _on_palette_changed(self, *_args) -> None:
        """``QApplication.paletteChanged`` 的槽：换主题后重算配色并重绘。"""
        if self._closing:
            return
        self._apply_theme()
        self.update()

    def _connect_palette_signal(self) -> None:
        """监听 ``QApplication.paletteChanged``：用户换样式表 / 系统切深色时换肤。

        ⚠️ 信号源是 **QApplication 单例**（不是自己），生命周期长于本控件，所以
        控件销毁时要断开 —— 见 :meth:`cleanup_before_tab_close`。否则关掉标签页后
        再换主题，Qt 会去调一个已经析构的控件（抛 ``RuntimeError`` 或直接崩）。
        """
        if self._palette_hooked:
            return
        try:
            app = QApplication.instance()
            if app is not None:
                app.paletteChanged.connect(self._on_palette_changed)
                self._palette_hooked = True
        except Exception as err:            # pragma: no cover
            print(f'Lianliankan: 未能监听主题变化（{err}）')

    def _disconnect_palette_signal(self) -> None:
        """断开主题信号（控件销毁前必须做，理由见 :meth:`_connect_palette_signal`）。"""
        if not self._palette_hooked:
            return
        self._palette_hooked = False
        try:
            app = QApplication.instance()
            if app is not None:
                app.paletteChanged.disconnect(self._on_palette_changed)
        except Exception:
            pass                            # 已断连 / 已销毁都无所谓

    def _bind_close_callback(self) -> None:
        """把自己接到宿主的关标签流程上（由 :func:`show_lianliankan` 调用）。

        沿 ``parent()`` 往上找 ``TabWidget``（要的是 ``close_tab_object``）。
        ⚠️ 找不到就保持 ``None``：那时 ``Esc`` 退回 ``self.close()``，
        在独立窗口（``test_1()``）场景下正是对的。
        """
        self._connect_palette_signal()
        node = self.parent()
        while node is not None:
            close = getattr(node, 'close_tab_object', None)
            if callable(close):
                self.close_callback = lambda: close(self)
                return
            node = node.parent()

    # ------------------------------------------------------------ 生命周期
    def showEvent(self, event):             # noqa: N802
        """进入标签页：续上计时器、重新对齐主题、抢焦点。"""
        super().showEvent(event)
        if self._closing:
            return
        self._apply_theme()
        if self.avatars and not self.timer.isActive():
            self.timer.start(max(1, int(1000 / FPS)))
        self.setFocus()

    def hideEvent(self, event):             # noqa: N802
        """离开标签页：停表。

        ⚠️ **停表省 CPU**，而且离屏期间本来就不需要动画 —— 那是"补偿"而不是
        "暂停游戏"：连连看没有倒计时，回来接着玩即可。
        """
        if self.timer.isActive():
            self.timer.stop()
        super().hideEvent(event)

    def cleanup_before_tab_close(self):
        """关闭标签页前的收尾（``TabWidget.close_tab`` 会 duck-typing 探测并调用）。

        ⚠️ 不许阻塞：这里只停表、断连，不等任何东西（本控件没有后台线程）。

        ⚠️ **顺序要紧**：先置 ``_closing`` 并停表断连。置位之后再触发的
        ``hideEvent`` 就不会去动状态；停表则保证 ``_frame`` 不会在销毁过程中
        再次进来（``deleteLater`` 与计时器回调都在事件循环里）。
        """
        self._closing = True
        try:
            self.timer.stop()
            try:
                self.timer.timeout.disconnect()
            except Exception:
                pass                        # 没连过 / 已断连都无所谓
            # ⚠️ 必须断开主题信号：它连在 QApplication 单例上，比本控件活得久。
            self._disconnect_palette_signal()
        except Exception as err:
            print(f'Error when closing lianliankan tab: {err}')

    def refresh(self):
        """GUI 刷新钩子（``MainWindow`` 每次切到本页都会调）。

        ⚠️ 必须**非常轻**：切标签是高频动作，里面不能读磁盘、不能重画布局。
        画面本来就由计时器逐帧重绘，这里只需让控件重绘一次即可。
        """
        if not self._closing:
            self.update()

    def keyPressEvent(self, ev):            # noqa: N802
        """按键：原版行为之上，把 ``Esc`` 接到宿主的关标签流程。"""
        if ev.key() == Qt.Key.Key_Escape and self.close_callback is not None:
            # ⚠️ 走宿主（``TabWidget.close_tab``）而不是 ``self.close()``：
            #    后者对标签页里的控件**不会**真正关掉标签，只是隐藏。
            #    只有在独立窗口（``test_1()``）里才退回 ``self.close()``。
            self.close_callback()
            return
        super().keyPressEvent(ev)


def show_lianliankan():
    """显示「连连看」标签页 —— 一个彩蛋（与「方块」二选一）。

    入口在「关于」页面的**「彩蛋」按钮**（见 ``zmlx/ui/tabs/about.py``），
    故意不挂菜单：它不是功能，是留给翻到「关于」页的人的惊喜。
    ⚠️ 那个按钮**每次点击**在本游戏与「螺螺是方块」之间各 1/2 概率随机。

    这个函数同时是 GUI 命令（``gui.show_lianliankan()``）。

    ⚠️ **刻意不设 ``widget.gui_restore``**：那是「重启后自动恢复本标签页」用的。
    游戏是个彩蛋：用户上次随手点开不代表下次启动还想接着玩，每次开机自动弹
    一个吃 CPU 的游戏标签页更不合适。要接着玩，再点一次「彩蛋」即可。

    ⚠️ 只通过 ``gui.get_widget`` 打开（而不是直接 ``LianliankanView()``）：
    这样标签页只会有**一个**，重复调用只是把已有页面切到前面 —— 对游戏尤其
    重要，开两局会各跑一个 60 FPS 的计时器。
    """
    from zmlx.ui import gui

    def oper(widget):
        # ★ 把"退出游戏"接到宿主的关标签流程上，并连上主题信号。
        #   ⚠️ 必须在这里做：控件此时已经 addTab 进 TabWidget，parent() 链才通得了。
        widget._bind_close_callback()

    gui.get_widget(
        LianliankanView, caption=CAPTION, on_top=True,
        icon='demo', oper=oper,
        tooltip='连连看：左键消除、右键/F1 提示、空格洗牌、R 重开、Esc 退出')


@execute_once(file=__file__)
def setup_ui():
    """注册 GUI 命令并挂菜单「**帮助 → 彩蛋 → 连连看**」。

    ⚠️ 本插件声明了 ``# ** enabled = False``（默认不加载）。用户若在「设置 →
    插件」里勾上它，本函数才会被 ``run_setup`` 执行 —— 于是菜单才出现。
    换句话说：**菜单的可见性就是「用户有没有启用这个彩蛋」**，不需要另外的开关。

    ⚠️ 作为插件，顶层**必须自己调**这个函数（见文件末尾）—— 没有谁会替它调。
    """
    from zmlx.ui import gui
    gui.add_func('show_lianliankan', show_lianliankan)
    gui.add_action(
        menu=['帮助', '彩蛋'],
        text='连连看',
        slot=show_lianliankan,
        tooltip='彩蛋游戏：连连看（左键消除、右键/F1 提示、空格洗牌、R 重开）',
    )


def test_1():
    """直接运行本文件时的自测：单独开一个窗口把游戏跑起来。"""
    if not HAVE_QT:
        print('No Qt binding available.')
        return
    app = QApplication.instance() or QApplication([])
    widget = LianliankanView()
    widget.resize(BASE_W, BASE_H)
    widget.show()
    app.exec()


if __name__ == '__zml_plugin__':
    # 插件机制执行时 ``__name__`` 是 ``'__zml_plugin__'``：只注册命令，别开窗口。
    setup_ui()
elif __name__ == '__main__':
    # ``python lianliankan.py`` 直接运行：开一个窗口自测。
    test_1()
